-- Administratör som undervisar (Users.teaches), del 4: krisläge, mentor och rapporteringsgrad (20270219090000_en_undervisande_administrator_svarar_i_larmet_ar_mentor_och_rapporterar), PRODUKTION, FÖRE migreringen, EFTER C1 (20270218090000; produktionens ordning, granskning 327).
-- Bara läsning: en SELECT per rad, kolumnerna check, got, expected, ok. Text som ordnas har COLLATE "C" (produktionen sorterar en_US, provdatabaserna C).
-- Migreringens sha256: a7e634696ce8c9716505f82cf39d0e7039c1b63ffc8d069ce34d68f4cae96de6
-- Kör som ägaren: psql -X -tA -F '|' -v ON_ERROR_STOP=1 -f <fil>  (valfritt med PGOPTIONS='-c default_transaction_read_only=on'). Förväntat: varje rad slutar på |t.
-- Rader med expected 'jämför med före/efter' är räknetal och fingeravtryck som alltid är ok = true: spara got och jämför med motsvarande rad i den andra filen.
-- Förväntade värden är lästa ur engångsdatabaser på Postgres 17 (main 202a4a9e, 220 migreringar). Produktionens egna siffror (serverversion, antal och fingeravtryck av migrationsrader) sätts efter
-- produktionens rader: F04-F06 och E03-E04 beror på vilka lägre migreringar som är körda före den här (till exempel 20270218090000, C1).
-- KÖR INTE MIGRERINGEN MEDAN ETT LARM ÄR ÖPPET: raden F09 ska vara 0.
-- Är en rad röd: stanna och läs got. En funktion eller policy vars md5 inte är den förväntade har ändrats av en annan gren sedan main 202a4a9e: migreringen patchar texten ur katalogen och stoppar själv (utan att något ändras).
SELECT 'F01 den här migreringen är inte körd' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM _prisma_migrations WHERE migration_name = '20270219090000_en_undervisande_administrator_svarar_i_larmet_ar_mentor_och_rapporterar')::text AS g) s;
SELECT 'F02 ingen migrering med den här stämpeln eller en senare finns' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM _prisma_migrations WHERE left(migration_name, 14) COLLATE "C" >= '20270219090000')::text AS g) s;
SELECT 'F03 ingen migrering är ofullbordad eller återrullad' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM _prisma_migrations WHERE finished_at IS NULL OR rolled_back_at IS NOT NULL)::text AS g) s;
SELECT 'F04 senaste körda migreringen (mains senaste; samordnaren sätter produktionens egen om en annan körts, till exempel 20270218090000)' AS check, g AS got, '20270218090000_ett_block_kan_forlaggas' AS expected, coalesce(g = '20270218090000_ett_block_kan_forlaggas', false) AS ok FROM (SELECT (SELECT migration_name FROM _prisma_migrations WHERE finished_at IS NOT NULL ORDER BY migration_name COLLATE "C" DESC LIMIT 1)::text AS g) s;
SELECT 'F05 antal körda migreringar (mains, 202a4a9e)' AS check, g AS got, '221' AS expected, coalesce(g = '221', false) AS ok FROM (SELECT (SELECT count(*) FROM _prisma_migrations WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL)::text AS g) s;
SELECT 'F06 migreringsnamnens fingeravtryck (md5 av namnen ordnade COLLATE "C", mains)' AS check, g AS got, 'c70d0af252cb03941d09e6cc56605b16' AS expected, coalesce(g = 'c70d0af252cb03941d09e6cc56605b16', false) AS ok FROM (SELECT (SELECT md5(string_agg(migration_name, ',' ORDER BY migration_name COLLATE "C")) FROM _prisma_migrations WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL)::text AS g) s;
SELECT 'F07 PR 1 och PR 3 är körda (20270212090000 och 20270216090000): markeringen och lärarens egna armar finns' AS check, g AS got, '2' AS expected, coalesce(g = '2', false) AS ok FROM (SELECT (SELECT count(*) FROM _prisma_migrations WHERE left(migration_name, 14) IN ('20270212090000', '20270216090000') AND finished_at IS NOT NULL AND rolled_back_at IS NULL)::text AS g) s;
SELECT 'F08 hjälparen och kolumnen finns (app.current_user_teaches, Users.teaches): armarna och funktionerna frågar efter dem' AS check, g AS got, '2' AS expected, coalesce(g = '2', false) AS ok FROM (SELECT (SELECT (SELECT count(*) FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname = 'current_user_teaches') + (SELECT count(*) FROM pg_attribute WHERE attrelid = '"Users"'::regclass AND attname = 'teaches' AND NOT attisdropped))::text AS g) s;
