SELECT 'F33 de tre policyernas kommando och roller (main)' AS check, g AS got, 'CrisisReports.crisis_reports_teacher_found_insert=a/app_authenticated CrisisReports.crisis_reports_teacher_free_insert=a/app_authenticated CrisisReports.crisis_reports_teacher_insert=a/app_authenticated' AS expected, coalesce(g = 'CrisisReports.crisis_reports_teacher_found_insert=a/app_authenticated CrisisReports.crisis_reports_teacher_free_insert=a/app_authenticated CrisisReports.crisis_reports_teacher_insert=a/app_authenticated', false) AS ok FROM (SELECT (SELECT string_agg(c.relname || '.' || pol.polname || '=' || pol.polcmd::text || '/' || (SELECT string_agg(CASE WHEN o = 0 THEN 'PUBLIC' ELSE (SELECT rolname::text FROM pg_roles WHERE oid = o) END, ',' ORDER BY 1) FROM unnest(pol.polroles) o), ' ' ORDER BY c.relname COLLATE "C", pol.polname COLLATE "C") FROM pg_policy pol JOIN pg_class c ON c.oid = pol.polrelid AND c.relnamespace = 'public'::regnamespace WHERE (c.relname = 'CrisisReports' AND pol.polname = 'crisis_reports_teacher_insert') OR (c.relname = 'CrisisReports' AND pol.polname = 'crisis_reports_teacher_found_insert') OR (c.relname = 'CrisisReports' AND pol.polname = 'crisis_reports_teacher_free_insert'))::text AS g) s;
SELECT 'F34 ingen policy på CrisisReports frågar efter markeringen än' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM pg_policy p WHERE p.polrelid = '"CrisisReports"'::regclass AND (coalesce(pg_get_expr(p.polqual, p.polrelid), '') || coalesce(pg_get_expr(p.polwithcheck, p.polrelid), '')) LIKE '%current_user_teaches%')::text AS g) s;
SELECT 'F35 de tolv funktionerna som lämnas som de är (md5 av prosrc, main)' AS check, g AS got, '211db706768e966806dc8297625d1584' AS expected, coalesce(g = '211db706768e966806dc8297625d1584', false) AS ok FROM (SELECT (SELECT md5(string_agg(p.proname || ':' || md5(p.prosrc), ',' ORDER BY p.proname COLLATE "C")) FROM pg_proc p WHERE p.pronamespace = 'app'::regnamespace AND p.proname IN ('crisis_may_start', 'crisis_report_is_stamped', 'crisis_answers_for', 'crisis_window_open', 'crisis_call_window_open', 'crisis_has_no_call_in', 'crisis_pupil_call', 'class_teacher_actor', 'cover_request_sender', 'checklist_taught_ids', 'current_user_teaches', 'cover_confirm'))::text AS g) s;
SELECT 'F36 funktionernas art och rättigheter (säkerhetsdefiniering, volatilitet, search_path, proacl) för de tio (main)' AS check, g AS got, 'absence_stats_lessons=false/s/- absence_watch_digest_plan=true/s/search_path=public, pg_temp absence_watch_is_mentor_of=true/s/search_path=public, pg_temp absence_watch_mentees=false/s/- ack_mentee_ids=true/s/search_path=public, pg_temp leave_mentors=false/s/- leave_mine_to_decide=true/s/search_path=public, pg_temp leave_request_taken=true/s/search_path=public, pg_temp lesson_move_is_mentor=true/s/search_path=public, pg_temp reporting_lessons=false/s/- | absence_stats_lessons={postgres=X/postgres} absence_watch_digest_plan={postgres=X/postgres} absence_watch_is_mentor_of={postgres=X/postgres,app_authenticated=X/postgres} absence_watch_mentees={postgres=X/postgres} ack_mentee_ids={postgres=X/postgres,app_authenticated=X/postgres} leave_mentors={postgres=X/postgres} leave_mine_to_decide={postgres=X/postgres,app_authenticated=X/postgres} leave_request_taken={postgres=X/postgres,app_authenticated=X/postgres} lesson_move_is_mentor={postgres=X/postgres,app_authenticated=X/postgres} reporting_lessons={postgres=X/postgres}' AS expected, coalesce(g = 'absence_stats_lessons=false/s/- absence_watch_digest_plan=true/s/search_path=public, pg_temp absence_watch_is_mentor_of=true/s/search_path=public, pg_temp absence_watch_mentees=false/s/- ack_mentee_ids=true/s/search_path=public, pg_temp leave_mentors=false/s/- leave_mine_to_decide=true/s/search_path=public, pg_temp leave_request_taken=true/s/search_path=public, pg_temp lesson_move_is_mentor=true/s/search_path=public, pg_temp reporting_lessons=false/s/- | absence_stats_lessons={postgres=X/postgres} absence_watch_digest_plan={postgres=X/postgres} absence_watch_is_mentor_of={postgres=X/postgres,app_authenticated=X/postgres} absence_watch_mentees={postgres=X/postgres} ack_mentee_ids={postgres=X/postgres,app_authenticated=X/postgres} leave_mentors={postgres=X/postgres} leave_mine_to_decide={postgres=X/postgres,app_authenticated=X/postgres} leave_request_taken={postgres=X/postgres,app_authenticated=X/postgres} lesson_move_is_mentor={postgres=X/postgres,app_authenticated=X/postgres} reporting_lessons={postgres=X/postgres}', false) AS ok FROM (SELECT ((SELECT string_agg(p.proname || '=' || p.prosecdef::text || '/' || p.provolatile::text || '/' || coalesce(array_to_string(p.proconfig, ','), '-'), ' ' ORDER BY p.proname COLLATE "C") FROM pg_proc p WHERE p.pronamespace = 'app'::regnamespace AND p.proname IN ('reporting_lessons', 'absence_stats_lessons', 'leave_mentors', 'absence_watch_mentees', 'absence_watch_digest_plan', 'leave_mine_to_decide', 'leave_request_taken', 'absence_watch_is_mentor_of', 'ack_mentee_ids', 'lesson_move_is_mentor')) || ' | ' || (SELECT string_agg(p.proname || '=' || coalesce(p.proacl::text, 'default'), ' ' ORDER BY p.proname COLLATE "C") FROM pg_proc p WHERE p.pronamespace = 'app'::regnamespace AND p.proname IN ('reporting_lessons', 'absence_stats_lessons', 'leave_mentors', 'absence_watch_mentees', 'absence_watch_digest_plan', 'leave_mine_to_decide', 'leave_request_taken', 'absence_watch_is_mentor_of', 'ack_mentee_ids', 'lesson_move_is_mentor')))::text AS g) s;
SELECT 'F37 ingen person är markerad som undervisande (en markerad får armarna och funktionerna vid migreringen: förväntat 0 i produktionen)' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM "Users" WHERE teaches)::text AS g) s;
SELECT 'F38 rättigheter per roll på CrisisReports (main)' AS check, g AS got, 'anon:CrisisReports=- app_authenticated:CrisisReports=INSERT,SELECT authenticated:CrisisReports=- service_role:CrisisReports=SELECT' AS expected, coalesce(g = 'anon:CrisisReports=- app_authenticated:CrisisReports=INSERT,SELECT authenticated:CrisisReports=- service_role:CrisisReports=SELECT', false) AS ok FROM (SELECT (SELECT string_agg(r.rolname || ':' || t || '=' || coalesce((SELECT string_agg(p, ',' ORDER BY p COLLATE "C") FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p WHERE has_table_privilege(r.rolname, ('public."' || t || '"')::regclass, p)), '-'), ' ' ORDER BY r.rolname COLLATE "C", t COLLATE "C") FROM pg_roles r, unnest(ARRAY['CrisisReports']) t WHERE r.rolname IN ('anon', 'authenticated', 'app_authenticated', 'service_role'))::text AS g) s;
SELECT 'F39 ingen API-roll håller MAINTAIN på CrisisReports (17: 0, 16: n/a)' AS check, g AS got, '0 eller n/a' AS expected, coalesce(g = '0' OR g = 'n/a', false) AS ok FROM (SELECT (SELECT CASE WHEN current_setting('server_version_num')::integer >= 170000 THEN (SELECT count(*)::text FROM pg_roles r, unnest(ARRAY['CrisisReports']) t WHERE r.rolname IN ('anon', 'authenticated', 'app_authenticated', 'service_role') AND has_table_privilege(r.rolname, ('public."' || t || '"')::regclass, 'MAINTAIN')) ELSE 'n/a' END)::text AS g) s;
SELECT 'F40 den som kör äger CrisisReports (migreringen ändrar policyerna där)' AS check, g AS got, '1' AS expected, coalesce(g = '1', false) AS ok FROM (SELECT (SELECT count(*) FROM pg_class WHERE oid IN ('"CrisisReports"'::regclass) AND pg_get_userbyid(relowner) = current_user)::text AS g) s;
SELECT 'F41 ingen annan session har en transaktion äldre än en sekund som håller ett lås på CrisisReports (migreringen tar låset NOWAIT i 30 s och ger upp)' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(DISTINCT l.pid) FROM pg_locks l JOIN pg_stat_activity a ON a.pid = l.pid WHERE l.locktype = 'relation' AND l.granted AND l.pid <> pg_backend_pid() AND l.relation IN ('"CrisisReports"'::regclass) AND a.xact_start < now() - interval '1 second')::text AS g) s;
SELECT 'F42 ingen förberedd transaktion (pg_prepared_xacts) hänger kvar' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM pg_prepared_xacts)::text AS g) s;
SELECT 'F43 ingen annan session väntar på ett lås på CrisisReports' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM pg_locks l WHERE l.locktype = 'relation' AND NOT l.granted AND l.relation IN ('"CrisisReports"'::regclass))::text AS g) s;
SELECT 'F44 serverversion' AS check, (SELECT current_setting('server_version_num'))::text AS got, 'jämför med före/efter' AS expected, true AS ok;
SELECT 'F45 CrisisReports, CrisisAlarms, LeaveRequests: antal rader' AS check, (SELECT (SELECT count(*) FROM "CrisisReports") || '/' || (SELECT count(*) FROM "CrisisAlarms") || '/' || (SELECT count(*) FROM "LeaveRequests"))::text AS got, 'jämför med före/efter' AS expected, true AS ok;
SELECT 'F46 fingeravtryck av alla app- och public-funktioner utom de tio och den nya (ändras inte)' AS check, (SELECT md5(string_agg(p.pronamespace::regnamespace::text || '.' || p.proname::text || ':' || md5(p.prosrc), ',' ORDER BY p.pronamespace::regnamespace::text COLLATE "C", p.proname COLLATE "C", p.oid::regprocedure::text COLLATE "C")) FROM pg_proc p WHERE p.pronamespace IN ('app'::regnamespace, 'public'::regnamespace) AND p.prokind IN ('f', 'p') AND NOT (p.pronamespace = 'app'::regnamespace AND p.proname IN ('reporting_lessons', 'absence_stats_lessons', 'leave_mentors', 'absence_watch_mentees', 'absence_watch_digest_plan', 'leave_mine_to_decide', 'leave_request_taken', 'absence_watch_is_mentor_of', 'ack_mentee_ids', 'lesson_move_is_mentor', 'teaches_like')))::text AS got, 'jämför med före/efter' AS expected, true AS ok;
SELECT 'F47 fingeravtryck av alla policyer i public utom de tre (ändras inte)' AS check, (SELECT md5(string_agg(c.relname || '.' || pol.polname || ':' || pol.polcmd::text || ':' || coalesce(pg_get_expr(pol.polqual, pol.polrelid), '') || '|' || coalesce(pg_get_expr(pol.polwithcheck, pol.polrelid), '') || '|' || pol.polpermissive::text || '|' || pol.polroles::text, E'\n' ORDER BY c.relname COLLATE "C", pol.polname COLLATE "C")) FROM pg_policy pol JOIN pg_class c ON c.oid = pol.polrelid AND c.relnamespace = 'public'::regnamespace WHERE NOT ((c.relname = 'CrisisReports' AND pol.polname = 'crisis_reports_teacher_insert') OR (c.relname = 'CrisisReports' AND pol.polname = 'crisis_reports_teacher_found_insert') OR (c.relname = 'CrisisReports' AND pol.polname = 'crisis_reports_teacher_free_insert')))::text AS got, 'jämför med före/efter' AS expected, true AS ok;
SELECT 'F48 den nya funktionen app.teaches_like finns inte än' AS check, g AS got, '0' AS expected, coalesce(g = '0', false) AS ok FROM (SELECT (SELECT count(*) FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname = 'teaches_like')::text AS g) s;
SELECT 'F49 antal app-funktioner (efter: före + 1, den nya funktionen)' AS check, (SELECT count(*) FROM pg_proc WHERE pronamespace = 'app'::regnamespace)::text AS got, 'jämför med före/efter' AS expected, true AS ok;
SELECT 'F50 antal policyer i public (efter: samma)' AS check, (SELECT count(*) FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid AND c.relnamespace = 'public'::regnamespace)::text AS got, 'jämför med före/efter' AS expected, true AS ok;
SELECT 'F51 Krislägets policyer (namnens fingeravtryck, ändras inte)' AS check, g AS got, '1afb6c937aeb486ae93924c736d095e7' AS expected, coalesce(g = '1afb6c937aeb486ae93924c736d095e7', false) AS ok FROM (SELECT (SELECT md5(string_agg(c.relname || '.' || pol.polname, ',' ORDER BY c.relname COLLATE "C", pol.polname COLLATE "C")) FROM pg_policy pol JOIN pg_class c ON c.oid = pol.polrelid AND c.relnamespace = 'public'::regnamespace WHERE c.relname LIKE 'Crisis%')::text AS g) s;
SELECT 'F52 antal personer per roll (administratörer, lärare, elever, vårdnadshavare)' AS check, (SELECT string_agg(role::text || '=' || n, ' ' ORDER BY role::text COLLATE "C") FROM (SELECT role, count(*) AS n FROM "Users" GROUP BY role) x)::text AS got, 'jämför med före/efter' AS expected, true AS ok;
